/*
 * Smoke test for the C bindings generated by SWIG's experimental C backend.
 * Plain C11, uses only the generated header.
 *
 * Usage: cosim_c_smoke <path to tests/data/msmi/OspSystemStructure.xml>
 */
#include "cosim_c_wrap.h"

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#ifdef _WIN32
#    include <windows.h>
#endif

static int failures = 0;

/* Short pause between status polls, so the simulation thread gets to run. */
static void pause_briefly(void)
{
#ifdef _WIN32
    Sleep(1);
#else
    struct timespec ts = {0, 1000000};
    nanosleep(&ts, NULL);
#endif
}

#define CHECK(cond)                                                     \
    do {                                                                \
        if (!(cond)) {                                                  \
            fprintf(stderr, "%s:%d: CHECK failed: %s\n", __FILE__,      \
                __LINE__, #cond);                                       \
            ++failures;                                                 \
        }                                                               \
    } while (0)

/* Returns nonzero (and prints/clears it) if an error is pending. */
static int check_error(const char* where)
{
    const int code = cosim_last_error_code();
    if (code == 0) return 0;
    const char* msg = cosim_last_error_message();
    fprintf(stderr, "%s: error %d: %s\n", where, code, msg);
    cosim_free_string(msg);
    cosim_clear_last_error();
    return 1;
}

static unsigned int find_ref(cosim_execution* exe, int sim, const char* name)
{
    cosim_model_description* md = cosim_execution_get_model_description(exe, sim);
    cosim_VariableDescriptionVector* vars = cosim_model_description_get_variables(md); /* owned copy */
    unsigned int ref = (unsigned int)-1;
    for (size_t i = 0; i < cosim_VariableDescriptionVector_size(vars); ++i) {
        cosim_variable_description* v = cosim_VariableDescriptionVector_get(vars, (int)i); /* owned copy */
        /* String getters return owned copies: release with cosim_free_string(). */
        const char* vname = cosim_variable_description_name_get(v);
        if (strcmp(vname, name) == 0) {
            ref = cosim_variable_description_reference_get(v);
        }
        cosim_free_string(vname);
        cosim_variable_description_delete(v);
    }

    /* Out-of-range access is an error, not a crash. */
    CHECK(cosim_VariableDescriptionVector_get(vars, 100000) == NULL);
    CHECK(cosim_last_error_code() != 0);
    cosim_clear_last_error();

    cosim_VariableDescriptionVector_delete(vars);
    /* Every returned object is owned: `vars` and each `v` were deleted above. */
    cosim_model_description_delete(md);
    return ref;
}

int main(int argc, char** argv)
{
    if (argc != 2) {
        fprintf(stderr, "usage: %s <OspSystemStructure.xml>\n", argv[0]);
        return 2;
    }
    cosim_set_output_level(cosim_level_warning);

    /* --- Error path: a failing call returns NULL and leaves a pending error. */
    cosim_configured_execution* bad = cosim_load_execution_from_ssp("/nonexistent/system.ssp", NULL);
    CHECK(bad == NULL);
    CHECK(cosim_last_error_code() == cosim_errc_zip_error);
    {
        const char* msg = cosim_last_error_message();
        printf("expected error: code=%d msg=%s\n", cosim_last_error_code(), msg);
        cosim_free_string(msg);
    }
    cosim_clear_last_error();
    CHECK(cosim_last_error_code() == 0);

    /* --- Load an OSP configuration. */
    cosim_configured_execution* le = cosim_load_execution_from_osp_config(argv[1], NULL);
    if (check_error("load_osp_config")) return 1;
    /* Owned: a new reference to the execution; delete it when done. */
    cosim_execution* exe = cosim_configured_execution_get_execution(le);

    cosim_StringIntMap* sims = cosim_configured_execution_simulators(le);
    CHECK(cosim_StringIntMap_size(sims) == 4);
    const int sim = cosim_StringIntMap_get(sims, "TrueIdentity");
    cosim_StringIntMap_delete(sims);

    const unsigned int integerIn = find_ref(exe, sim, "integerIn");
    const unsigned int integerOut = find_ref(exe, sim, "integerOut");
    CHECK(integerIn != (unsigned int)-1 && integerOut != (unsigned int)-1);

    /* --- Observer and manipulator. The C backend has no typed upcast
     *     functions: passing a derived object where a base is expected
     *     needs an explicit cast. */
    cosim_last_value_observer* obs = cosim_last_value_observer_new();
    cosim_override_manipulator* man = cosim_override_manipulator_new();
    cosim_execution_add_observer(exe, (cosim_observer*)obs);
    cosim_execution_add_manipulator(exe, (cosim_manipulator*)man);
    if (check_error("add observer/manipulator")) return 1;

    cosim_override_manipulator_override_integer_variable(man, sim, integerIn, 42);

    /* --- Run. */
    /* Times are int64 nanoseconds, as in libcosimc. */
    const int64_t t0 = cosim_execution_current_time(exe);
    CHECK(t0 == cosim_to_nanoseconds(0.01));
    CHECK(cosim_execution_step(exe) > 0.0);
    CHECK(cosim_execution_simulate_until(exe, t0 + cosim_to_nanoseconds(0.01)));
    if (check_error("simulate")) return 1;
    printf("time: %g s -> %g s\n", cosim_to_seconds(t0), cosim_to_seconds(cosim_execution_current_time(exe)));

    cosim_ValueReferenceVector* refs = cosim_ValueReferenceVector_new();
    cosim_ValueReferenceVector_push_back(refs, integerOut);
    cosim_IntVector* values = cosim_last_value_observer_get_integer(obs, sim, refs);
    CHECK(cosim_IntVector_size(values) == 1);
    CHECK(cosim_IntVector_get(values, 0) == 42);
    printf("integerOut = %d\n", cosim_IntVector_get(values, 0));

    /* --- Factory functions replacing constructors. */
    cosim_fixed_step_algorithm* algo = cosim_fixed_step_algorithm_create(cosim_to_nanoseconds(1e-3), 0);
    cosim_execution* exe2 = cosim_execution_new(0.0, (cosim_algorithm*)algo);
    CHECK(cosim_execution_current_time(exe2) == 0);

    /* --- add_fmu, get_simulators, non-blocking start and status. */
    {
        cosim_fixed_step_algorithm* algo3 = cosim_fixed_step_algorithm_create(cosim_to_nanoseconds(0.1), 0);
        cosim_execution* exe3 = cosim_execution_new(0, (cosim_algorithm*)algo3);
        const char* fmu = getenv("IDENTITY_FMU");
        CHECK(fmu != NULL);
        if (fmu) {
            CHECK(cosim_add_fmu(exe3, fmu, "a", 0, NULL) == 0);
            if (check_error("add_fmu")) return 1;
            cosim_SimulatorInfoVector* infos = cosim_execution_get_simulators(exe3);
            CHECK(cosim_SimulatorInfoVector_size(infos) == 1);
            cosim_simulator_info* info = cosim_SimulatorInfoVector_get(infos, 0); /* owned copy */
            const char* name = cosim_simulator_info_name_get(info);
            CHECK(strcmp(name, "a") == 0);
            cosim_free_string(name);
            cosim_simulator_info_delete(info);
            cosim_SimulatorInfoVector_delete(infos);

            cosim_execution_start_simulation(exe3);
            if (check_error("start_simulation")) return 1;
            int64_t t = 0;
            const time_t deadline = time(NULL) + 60; /* generous: valgrind is slow */
            while (t < cosim_to_nanoseconds(1.0) && time(NULL) < deadline) {
                cosim_execution_status* st = cosim_execution_get_status(exe3);
                t = cosim_execution_status_current_time_get(st);
                cosim_execution_status_delete(st);
                pause_briefly();
            }
            CHECK(t >= cosim_to_nanoseconds(1.0));
            cosim_execution_stop_simulation(exe3);
            while (cosim_execution_is_running(exe3)) pause_briefly();
            cosim_execution_status* st = cosim_execution_get_status(exe3);
            CHECK(cosim_execution_status_state_get(st) == cosim_execution_state_stopped);
            CHECK(cosim_execution_status_error_code_get(st) == cosim_errc_success);
            cosim_execution_status_delete(st);
        }
        cosim_execution_delete(exe3);
        cosim_fixed_step_algorithm_delete(algo3);
    }

    /* --- Cleanup: every object returned by the API is owned by the caller. */
    cosim_execution_delete(exe2);
    cosim_fixed_step_algorithm_delete(algo);
    cosim_IntVector_delete(values);
    cosim_ValueReferenceVector_delete(refs);
    cosim_override_manipulator_delete(man);
    cosim_last_value_observer_delete(obs);
    cosim_execution_delete(exe);
    cosim_configured_execution_delete(le);

    if (failures) {
        fprintf(stderr, "%d check(s) failed\n", failures);
        return 1;
    }
    printf("C smoke test OK\n");
    return 0;
}
